// Announce generation (TASK_antispam_amend7.md A+B): a 1–2 sentence cute
// kick notice, generated by the same model chain used for judging, with an
// independent short timeout (BOT_ANNOUNCE_TIMEOUT, default 8s, clamped
// 1s..20s) and no retries — any failure falls back to the local template
// pool in internal/bot.
//
// Post-processing contract (hard, all tested):
//  1. strip ```json fences, surrounding quotes, collapse to one line;
//  2. > 80 runes → truncate to 80;
//  3. missing subject → prefix "subject ";
//  4. compliance filter: URL, a @username other than the subject, phone /
//     wechat / qq style contact strings → reject (error → template fallback);
//  5. empty / whitespace-only → error.
package ai

import (
	"context"
	_ "embed"
	"fmt"
	"regexp"
	"strings"
	"time"

	openai "github.com/sashabaranov/go-openai"
)

// completionMessage aliases the chat message shape for the announce path.
type completionMessage = openai.ChatCompletionMessage

// Role aliases for the announce path.
const (
	roleSystem = openai.ChatMessageRoleSystem
	roleUser   = openai.ChatMessageRoleUser
)

// AnnouncePromptVersion identifies the embedded announce prompt revision.
const AnnouncePromptVersion = "announce_v1"

//go:embed prompts/announce_v1.txt
var promptAnnounce string

// AnnounceMaxLen caps the generated announcement after post-processing.
const AnnounceMaxLen = 80

// AnnounceTimeoutDefault is the fallback when no timeout is configured.
const AnnounceTimeoutDefault = 8 * time.Second

// AnnounceTimeoutMin / Max clamp the configured timeout.
const (
	AnnounceTimeoutMin = 1 * time.Second
	AnnounceTimeoutMax = 20 * time.Second
)

// urlPattern matches http(s) links and bare domains ("t.me/xxx",
// "example.com", "www.foo.cn").
var urlPattern = regexp.MustCompile(`(?i)(?:\b|//)(?:https?://|www\.)?[a-z0-9-]{1,63}\.(?:com|cn|net|org|io|me|xyz|cc|vip|top|club|site|shop|online|link|app|dev|info|biz)(?:\b|/)`)

// atPattern matches a @username mention.
var atPattern = regexp.MustCompile(`@[A-Za-z][A-Za-z0-9_]{2,}`)

// contactPattern matches phone numbers (11-digit CN or spaced), and
// wechat/qq contact style strings.
var contactPattern = regexp.MustCompile(`(?i)\b1[3-9]\d{9}\b|\b\d[\d\s-]{8,11}\d\b|(?i)(?:微信|加v|加v信|vx|wx|扣扣|qq|飞机|tg|telegram)[号:：\s]*[a-z0-9_-]{3,}`)

// Announce builds the user message for the announce prompt.
func announceUserMessage(subject, category string) string {
	var b strings.Builder
	b.WriteString("请为下面的送客事件生成一条公告：\n")
	b.WriteString("<subject>\n" + subject + "\n</subject>")
	if category != "" {
		b.WriteString("\n<category>\n" + category + "\n</category>")
	}
	return b.String()
}

// Announce walks the SAME model fallback chain once (pro → flash →
// ultraspeed); the first model whose raw text survives post-processing wins.
// It never retries a compliant-but-rejected output: a compliance violation
// fails the whole call so the caller uses the local template pool (the next
// model would likely reproduce the same contact string).
func (c *Client) Announce(ctx context.Context, subject, category string) (string, error) {
	subject = strings.TrimSpace(subject)
	if subject == "" {
		return "", fmt.Errorf("announce: empty subject")
	}
	timeout := c.announceTimeout()
	sys := promptAnnounce
	user := announceUserMessage(subject, category)
	msgs := []completionMessage{{Role: roleSystem, Content: sys}, {Role: roleUser, Content: user}}

	start := time.Now()
	for _, model := range c.cfg.Models {
		text, err := c.announceOnce(ctx, model, msgs, timeout)
		if err != nil {
			if c.cfg.Logger != nil {
				c.cfg.Logger.Warn("announce_model_attempt_failed",
					"model", model, "err", err.Error(),
					"prompt_version", AnnouncePromptVersion)
			}
			continue
		}
		out, err := CleanAnnounce(text, subject)
		if err != nil {
			if c.cfg.Logger != nil {
				c.cfg.Logger.Warn("announce_noncompliant",
					"model", model, "err", err.Error(),
					"prompt_version", AnnouncePromptVersion)
			}
			return "", err
		}
		if c.cfg.Logger != nil {
			c.cfg.Logger.Info("announce_generated_ai",
				"model", model,
				"ms", time.Since(start).Milliseconds(),
				"prompt_version", AnnouncePromptVersion)
		}
		return out, nil
	}
	return "", fmt.Errorf("announce: all models in chain failed")
}

// announceOnce runs one model round trip with the independent short timeout.
func (c *Client) announceOnce(ctx context.Context, model string, msgs []completionMessage, timeout time.Duration) (string, error) {
	ctxT, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req := openai.ChatCompletionRequest{
		Model:           model,
		Stream:          false,
		ReasoningEffort: openai.ReasoningEffortNone, // same thinking-off contract as Classify
		Messages:        msgs,
	}
	req.ChatTemplateKwargs = map[string]any{
		"enable_thinking": false,
	}
	resp, err := c.client.CreateChatCompletion(ctxT, req)
	if err != nil {
		return "", err
	}
	if len(resp.Choices) == 0 {
		// Same 200-with-error-envelope probe as classifyOnce: pool codes ride
		// in a 200 body that go-openai decodes as an empty response.
		if code := c.lastBodyErrorCode(); code != "" {
			return "", fmt.Errorf("gateway body error: %s", code)
		}
		return "", fmt.Errorf("no choices in response")
	}
	return resp.Choices[0].Message.Content, nil
}

// announceTimeout resolves the effective per-attempt timeout (clamped).
func (c *Client) announceTimeout() time.Duration {
	d := c.announceTO
	if d <= 0 {
		d = AnnounceTimeoutDefault
	}
	if d < AnnounceTimeoutMin {
		return AnnounceTimeoutMin
	}
	if d > AnnounceTimeoutMax {
		return AnnounceTimeoutMax
	}
	return d
}

// CleanAnnounce post-processes and compliance-filters one raw model output.
// It is exported so the bot package's template path and tests can reuse the
// exact same pipeline. Steps (B.4):
//  1. strip fences / quotes / newlines;
//  2. cap at AnnounceMaxLen runes;
//  3. missing subject → prefix;
//  4. URL / foreign @mention / contact-style string → error;
//  5. empty → error.
func CleanAnnounce(text, subject string) (string, error) {
	out := normalizeAnnounceText(text)
	if strings.TrimSpace(out) == "" {
		return "", fmt.Errorf("announce: empty output")
	}
	if len([]rune(out)) > AnnounceMaxLen {
		out = string([]rune(out)[:AnnounceMaxLen])
	}
	if !strings.Contains(out, subject) {
		// Missing subject → prefix; the prefix may push the total past the
		// cap, so re-truncate (subject first, tail cut).
		out = subject + " " + out
		if len([]rune(out)) > AnnounceMaxLen {
			out = string([]rune(out)[:AnnounceMaxLen])
		}
	}
	if u := urlPattern.FindString(out); u != "" {
		return "", fmt.Errorf("announce: URL in output %q", u)
	}
	if m := atPattern.FindString(out); m != "" {
		// The mention is fine when the subject IS that username (with or
		// without the @ prefix); anything else is a foreign contact.
		plain := strings.TrimPrefix(m, "@")
		if !strings.EqualFold(subject, plain) && !strings.Contains(subject, m) {
			return "", fmt.Errorf("announce: foreign @mention %q", m)
		}
	}
	if s := contactPattern.FindString(out); s != "" {
		return "", fmt.Errorf("announce: contact-style string %q", s)
	}
	return out, nil
}

// normalizeAnnounceText strips markdown fences, surrounding quotes and
// newlines, and collapses whitespace.
func normalizeAnnounceText(text string) string {
	s := stripFences(text)
	s = strings.TrimSpace(s)
	// Full-body quotes: "..." / “...” / '...' around the whole output.
	if r := []rune(s); len(r) >= 2 {
		first, last := r[0], r[len(r)-1]
		if (first == '"' && last == '"') || (first == '“' && last == '”') || (first == '\'' && last == '\'') {
			s = strings.TrimSpace(string(r[1 : len(r)-1]))
		}
	}
	// Multi-line → one line (also drops the fence residue lines).
	s = strings.Join(strings.Fields(strings.ReplaceAll(s, "\n", " ")), " ")
	return strings.TrimSpace(s)
}
